<?php use App\Core\Database;$month=preg_match('/^\d{4}-\d{2}$/',(string)($_GET['month']??''))?$_GET['month']:date('Y-m');$summary=Database::query("SELECT COUNT(DISTINCT a.patient_id) patients,COUNT(t.id) services,COALESCE(SUM(t.cost),0) revenue FROM treatments t JOIN appointments a ON a.id=t.appointment_id WHERE DATE_FORMAT(a.appointment_date,'%Y-%m')=?",[$month])->fetch();$login=(int)Database::query("SELECT COUNT(*) FROM login_logs WHERE DATE_FORMAT(logged_in_at,'%Y-%m')=?",[$month])->fetchColumn();$services=Database::query("SELECT a.service,COUNT(*) total,COALESCE(SUM(t.cost),0) revenue FROM treatments t JOIN appointments a ON a.id=t.appointment_id WHERE DATE_FORMAT(a.appointment_date,'%Y-%m')=? GROUP BY a.service ORDER BY total DESC",[$month])->fetchAll();page_header('รายงานและสถิติ','สรุปข้อมูลจริงตามเดือน');?>
<form method="get" class="filter-bar"><input type="hidden" name="page" value="reports"><label>เดือน <input type="month" name="month" value="<?=htmlspecialchars($month)?>"></label><button class="outline-button">แสดงรายงาน</button></form><div class="stats-grid"><?php stat_card('฿',number_format((float)$summary['revenue'],2),'รายรับรวม','บาท','green');stat_card('✚',(string)$summary['services'],'บริการทั้งหมด','ครั้ง');stat_card('♙',(string)$summary['patients'],'ผู้รับบริการ','คน','purple');stat_card('↗',(string)$login,'เข้าใช้ระบบ','ครั้ง','orange');?></div><section class="panel"><?php data_table(['บริการ','จำนวน','รายรับ'],array_map(fn($r)=>[$r['service'],$r['total'],number_format((float)$r['revenue'],2)],$services));?></section>
